INSERT INTO public.help_articles (category_key, category_icon, category_order, question_key, question_order, is_active, translations) VALUES
('getting_started', '🚀', 1, 'what_is_app', 1, true, '{"fr": {"category": "Premiers pas", "question": "Qu''est-ce que Smart Trade Kit ?", "answer": "Smart Trade Kit est votre compagnon de trading intelligent. Il vous permet de suivre vos trades, analyser vos performances, tenir un journal de trading et améliorer votre discipline grâce à des défis et statistiques avancées."}, "en": {"category": "Getting Started", "question": "What is Smart Trade Kit?", "answer": "Smart Trade Kit is your intelligent trading companion. It allows you to track your trades, analyze your performance, keep a trading journal, and improve your discipline through challenges and advanced statistics."}}'),
('getting_started', '🚀', 1, 'how_to_add_trade', 2, true, '{"fr": {"category": "Premiers pas", "question": "Comment ajouter un trade ?", "answer": "Cliquez sur \"Ajout de Trade\" dans le menu latéral. Remplissez les informations de votre trade : actif, direction (achat/vente), prix d''entrée, prix de sortie, taille de lot, etc. Vous pouvez aussi ajouter des notes et des émotions pour votre journal."}, "en": {"category": "Getting Started", "question": "How do I add a trade?", "answer": "Click on \"Add Trade\" in the sidebar menu. Fill in your trade details: asset, direction (buy/sell), entry price, exit price, lot size, etc. You can also add notes and emotions for your journal."}}'),
('getting_started', '🚀', 1, 'how_to_set_capital', 3, true, '{"fr": {"category": "Premiers pas", "question": "Comment définir mon capital initial ?", "answer": "Lors de votre première utilisation, une fenêtre vous proposera de définir votre capital. Vous pouvez aussi le faire depuis les Paramètres. Le capital permet de calculer précisément votre ROI, drawdown et courbe d''équité."}, "en": {"category": "Getting Started", "question": "How do I set my initial capital?", "answer": "On first use, a dialog will prompt you to set your capital. You can also do it from Settings. The capital allows accurate calculation of your ROI, drawdown, and equity curve."}}'),
('trades', '📊', 2, 'edit_trade', 1, true, '{"fr": {"category": "Trades", "question": "Comment modifier un trade existant ?", "answer": "Allez dans l''Historique Complet, trouvez le trade que vous souhaitez modifier, puis cliquez sur l''icône de modification. Vous pourrez éditer tous les champs du trade."}, "en": {"category": "Trades", "question": "How do I edit an existing trade?", "answer": "Go to Full History, find the trade you want to modify, then click the edit icon. You can edit all trade fields."}}'),
('trades', '📊', 2, 'import_trades', 2, true, '{"fr": {"category": "Trades", "question": "Puis-je importer mes trades depuis MetaTrader ?", "answer": "Oui ! Utilisez la fonction d''import dans la page Ajout de Trade. Vous pouvez importer vos trades depuis un fichier CSV ou un rapport MetaTrader 4/5."}, "en": {"category": "Trades", "question": "Can I import trades from MetaTrader?", "answer": "Yes! Use the import function on the Add Trade page. You can import your trades from a CSV file or a MetaTrader 4/5 report."}}'),
('trades', '📊', 2, 'multi_accounts', 3, true, '{"fr": {"category": "Trades", "question": "Comment fonctionne le système multi-comptes ?", "answer": "Vous pouvez créer plusieurs comptes (Personnel, Prop Firm, Démo, etc.) depuis votre Profil. Chaque compte a ses propres trades, statistiques et journal. Utilisez le sélecteur de compte en haut pour basculer entre vos comptes."}, "en": {"category": "Trades", "question": "How does the multi-account system work?", "answer": "You can create multiple accounts (Personal, Prop Firm, Demo, etc.) from your Profile. Each account has its own trades, statistics, and journal. Use the account switcher at the top to switch between accounts."}}'),
('statistics', '📈', 3, 'how_stats_calculated', 1, true, '{"fr": {"category": "Statistiques", "question": "Comment sont calculées les statistiques ?", "answer": "Les statistiques sont calculées en temps réel à partir de vos trades. Le taux de victoire, le profit moyen, le drawdown et tous les indicateurs sont mis à jour automatiquement à chaque nouveau trade ajouté."}, "en": {"category": "Statistics", "question": "How are statistics calculated?", "answer": "Statistics are calculated in real-time from your trades. Win rate, average profit, drawdown, and all indicators are automatically updated with each new trade added."}}'),
('statistics', '📈', 3, 'what_is_drawdown', 2, true, '{"fr": {"category": "Statistiques", "question": "Qu''est-ce que le drawdown ?", "answer": "Le drawdown mesure la baisse maximale de votre capital depuis son plus haut niveau. C''est un indicateur clé de gestion des risques. Un drawdown de 10% signifie que votre capital a baissé de 10% par rapport à son pic."}, "en": {"category": "Statistics", "question": "What is drawdown?", "answer": "Drawdown measures the maximum decline of your capital from its peak level. It''s a key risk management indicator. A 10% drawdown means your capital dropped 10% from its peak."}}'),
('statistics', '📈', 3, 'what_is_r_multiple', 3, true, '{"fr": {"category": "Statistiques", "question": "Qu''est-ce que le R:R moyen ?", "answer": "Le R:R (Risk/Reward) moyen mesure le rapport entre vos gains et vos pertes. Un R:R de 2 signifie que vous gagnez en moyenne 2 fois ce que vous risquez. Un bon R:R combiné à un taux de victoire décent est la clé de la rentabilité."}, "en": {"category": "Statistics", "question": "What is the average R:R?", "answer": "The average R:R (Risk/Reward) measures the ratio between your gains and losses. An R:R of 2 means you earn on average twice what you risk. A good R:R combined with a decent win rate is the key to profitability."}}'),
('journal', '📓', 4, 'why_journal', 1, true, '{"fr": {"category": "Journal de Trading", "question": "Pourquoi tenir un journal de trading ?", "answer": "Le journal de trading vous permet de noter vos émotions, leçons et observations quotidiennes. C''est un outil essentiel pour identifier vos patterns comportementaux et améliorer votre discipline de trading."}, "en": {"category": "Trading Journal", "question": "Why keep a trading journal?", "answer": "The trading journal lets you record your emotions, lessons, and daily observations. It''s an essential tool for identifying behavioral patterns and improving your trading discipline."}}'),
('journal', '📓', 4, 'how_to_use_journal', 2, true, '{"fr": {"category": "Journal de Trading", "question": "Comment utiliser le journal ?", "answer": "Accédez au journal depuis le menu. Chaque jour, vous pouvez ajouter un objectif, des notes, des leçons apprises et évaluer votre journée. La checklist pré-trading vous aide à vous préparer avant chaque session."}, "en": {"category": "Trading Journal", "question": "How do I use the journal?", "answer": "Access the journal from the menu. Each day, you can add an objective, notes, lessons learned, and rate your day. The pre-trading checklist helps you prepare before each session."}}'),
('account', '⚙️', 5, 'change_currency', 1, true, '{"fr": {"category": "Compte & Paramètres", "question": "Comment changer la devise ?", "answer": "Allez dans Paramètres et sélectionnez votre devise préférée. Toutes vos statistiques et montants seront affichés dans la devise choisie."}, "en": {"category": "Account & Settings", "question": "How do I change the currency?", "answer": "Go to Settings and select your preferred currency. All your statistics and amounts will be displayed in the chosen currency."}}'),
('account', '⚙️', 5, 'data_security', 2, true, '{"fr": {"category": "Compte & Paramètres", "question": "Mes données sont-elles sécurisées ?", "answer": "Oui, toutes vos données sont chiffrées et stockées de manière sécurisée. Nous utilisons des politiques de sécurité strictes (RLS) pour garantir que seul vous avez accès à vos données. Vous pouvez aussi activer un code PIN pour protéger l''accès à l''application."}, "en": {"category": "Account & Settings", "question": "Is my data secure?", "answer": "Yes, all your data is encrypted and stored securely. We use strict security policies (RLS) to ensure only you have access to your data. You can also enable a PIN code to protect app access."}}'),
('account', '⚙️', 5, 'export_data', 3, true, '{"fr": {"category": "Compte & Paramètres", "question": "Puis-je exporter mes données ?", "answer": "Oui, vous pouvez exporter vos données depuis le Centre de Confidentialité dans les Paramètres. Vous pouvez télécharger toutes vos données au format JSON conformément au RGPD."}, "en": {"category": "Account & Settings", "question": "Can I export my data?", "answer": "Yes, you can export your data from the Privacy Center in Settings. You can download all your data in JSON format in compliance with GDPR."}}'),
('challenges', '🏆', 6, 'what_are_challenges', 1, true, '{"fr": {"category": "Défis & Gamification", "question": "Comment fonctionnent les défis ?", "answer": "Les défis sont des objectifs que vous devez atteindre pour gagner des points et monter en niveau. Il y a des défis quotidiens, hebdomadaires et secrets. Complétez-les pour améliorer votre discipline de trading !"}, "en": {"category": "Challenges & Gamification", "question": "How do challenges work?", "answer": "Challenges are goals you need to achieve to earn points and level up. There are daily, weekly, and secret challenges. Complete them to improve your trading discipline!"}}'),
('challenges', '🏆', 6, 'what_are_reward_chests', 2, true, '{"fr": {"category": "Défis & Gamification", "question": "Que sont les coffres de récompense ?", "answer": "Les coffres de récompense sont débloqués en atteignant certains paliers de points. Ils contiennent des bonus de points supplémentaires et vous motivent à rester discipliné dans votre trading."}, "en": {"category": "Challenges & Gamification", "question": "What are reward chests?", "answer": "Reward chests are unlocked by reaching certain point thresholds. They contain additional point bonuses and motivate you to stay disciplined in your trading."}}');
